{"implementation":"def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    if not isinstance(text, str) or not isinstance(passes, list) or not isinstance(max_rounds, int) or max_rounds < 0:
        raise ValueError('Invalid case structure')
    current = text
    applications = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            name = p['name']
            old = p['old']
            new = p['new']
            if not isinstance(name, str) or not isinstance(old, str) or not isinstance(new, str):
                raise ValueError('Pass fields must be strings')
            if old == '':
                continue
            pos = current.find(old)
            if pos != -1:
                current = current[:pos] + new + current[pos+len(old):]
                applications.append(name)
                changed = True
        if not changed:
            break
    fixed_point = True
    if max_rounds > 0:
        current = text
        applications = []
        changed_last = False
        for _ in range(max_rounds):
            changed = False
            for p in passes:
                name = p['name']
                old = p['old']
                new = p['new']
                if old == '':
                    continue
                pos = current.find(old)
                if pos != -1:
                    current = current[:pos] + new + current[pos+len(old):]
                    applications.append(name)
                    changed = True
            if not changed:
                fixed_point = True
                break
            else:
                changed_last = True
        else:
            fixed_point = not changed_last
    return {'text': current, 'applications': applications, 'fixed_point': fixed_point}
"}
